INSERT INTO blog_posts (
  title, slug, excerpt, status, featured, publish_date, 
  author_id, cover_image_url, body_json,
  seo_title, seo_description, seo_keywords
) VALUES (
  '🏎️ How Change Projects Are Like Cars',
  'how-change-projects-are-like-cars',
  'While assembling a team of great drivers to design and build your new car may seem ridiculous, it''s actually not too far off from how many organizations approach operational and digital transformation. Here''s why Phase Zero planning matters.',
  'published',
  false,
  '2024-05-01T12:00:00Z',
  '2f4747b9-52a2-46b6-be42-9812820d9657',
  'https://media.licdn.com/dms/image/v2/D5612AQFQY90-W9wXSg/article-cover_image-shrink_720_1280/article-cover_image-shrink_720_1280/0/1714586170025?e=2147483647&v=beta&t=PY8MnHumGlzakah6LigA_jSUzdXOFhEVg8gBhNAqCIM',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Imagine the following scenario:","type":"text"}]},{"type":"paragraph","content":[{"text":"You decide that, after 20 years of driving the same 2003 Honda CR-V, it''s time for a new car. While your CR-V is a reliable vehicle that can get you from Point A to B just fine, you''re starting to see:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\ud83d\udcb8 Pricier repair bills","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\ud83d\udc0c Slower performance","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"\ud83d\udcf1 A need for more modern features and functions","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"So, here''s what you do:","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Conduct some research on different cars based on what you''ve seen or heard about in ads or in speaking with others","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Visit a few car lots and maybe even test drive a couple cars","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Decide on the car you''d like, but know that you want to ensure it meets your needs and may require some additional configuration and feature design","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assemble a team made up of the best DRIVERS you know","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ask them to work together to design and build your new car","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Fast forward 6 months and you most likely have one of the following:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"No car (though they''re still meeting about 10+ hours a week to decide and agree upon a design that meets all needs)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that is \"done\" but looks, feels, and drives a LOT like your current 2003 CR-V","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that in no way meets your needs (e.g., an electric car when you mainly use it for long-distance drives, a manual when you don''t know how to use a clutch, Apple Car Play when you have an Android, and so on)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that is \"done\" but is so bloated with features and functionality that no one really knows how to turn it on or drive it properly (or really wants to)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that is \"done\" but is SLOWER than your current CR-V","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that is \"done\" but has so many safety features that you can''t even turn the damn thing on or take the car out of park without it beeping at you incessantly","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A car that is \"done\" but ended up costing you WAAAAAAY more $$$ than you ever could have imagined or budgeted","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"While this may seem like a ridiculous way to upgrade your car, it''s actually not too far off from how many organizations approach the upgrade to their operational process or system vehicles. They:","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a technology (or several)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assemble a team of leaders and SMEs who may know their job/dept, but not necessarily the WHY behind those actions or how to work together as a new team of DESIGNERS vs. simply doers","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Give them a target of \"Go Live\" (without really knowing how you drive, where, for how long)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pray for the best and wonder why the project is \"off track\"","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Over my almost 20 years of working alongside these organizations, I''ve seen this happen time and time again. And it''s why I founded ","type":"text"},{"text":"Painted Porch Strategies","type":"text","marks":[{"type":"bold"}]},{"text":". Our training, advisory, and coaching services center around this idea of ","type":"text"},{"text":"Phase Zero\u2122","type":"text","marks":[{"type":"bold"}]},{"text":" planning and preparation. BEFORE you begin your change journey (yes, that means even before you start shopping around for solutions or partners), it''s critical that you''re getting clarity and creating alignment on the WHAT, WHEN, WHERE, WHY, (and most importantly) WHO of your change initiative.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What is Phase Zero?","type":"text"}]},{"type":"paragraph","content":[{"text":"Phase Zero is the activities (training, advisory, evaluation, audit, coaching) that happen prior to kicking off your operational or digital transformation. Its aim is to ensure that your project is on time, on budget, and on purpose. It''s creating an innovative culture within your project and organizational teams to ensure that change is not just a moment, but a movement.","type":"text"}]},{"type":"paragraph","content":[{"text":"During Phase Zero, you''re:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assessing your organization''s readiness, mindset, and cultural health for change","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Understanding and knowing how to navigate the People side of change (which is where change, ultimately, happens)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Identifying and developing change team members and ambassadors to lean in, speak up, challenge current norms, and design and drive change that is transformational (vs. tinkering)","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Creating an engaged, accountable, value-based & future-focused culture of innovation and CANI (constant and never-ending improvement) so problems and opportunities for change are continually assessed, measured, designed, and executed","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Phase Zero is the critical phase that must happen BEFORE a single dollar, hour, license, or resource is spent in service to your transformation. It''s creating a change-ready organization who is prepared to lead your organization through its next phase of growth, transformation, and success.","type":"text"}]}]}',
  'How Change Projects Are Like Cars | Phase Zero Planning',
  'Why assembling great drivers to build your car is as flawed as how organizations approach digital transformation. Learn how Phase Zero planning changes the game.',
  ARRAY['change management', 'Phase Zero', 'digital transformation', 'organizational change', 'change readiness']
);

